def cardinality(left_unique, right_unique):
    if left_unique and right_unique:
        return "one-to-one"
    if left_unique:
        return "one-to-many"
    if right_unique:
        return "many-to-one"
    return "many-to-many"


for combo in [(True, False), (False, True), (True, True), (False, False)]:
    print(cardinality(*combo))

independent.solution:
def count_paths(edges, start, end, seen=()):
    if start == end:
        return 1
    total = 0
    for a, b in edges:
        for here, nxt in ((a, b), (b, a)):
            if here == start and nxt not in seen:
                total += count_paths(edges, nxt, end, seen + (start,))
    return total


def ambiguous(edges, tables):
    pairs = []
    for i, a in enumerate(sorted(tables)):
        for b in sorted(tables)[i + 1:]:
            if count_paths(edges, a, b) > 1:
                pairs.append((a, b))
    return pairs


star = [("Calendar", "Sales"), ("Customers", "Sales"), ("Products", "Sales")]
tables = ["Calendar", "Customers", "Products", "Sales"]
print(ambiguous(star, tables))
print(ambiguous(star + [("Calendar", "Customers")], tables))
